query.query:
mutation createPhoto($title: String!, $description: String!) {
  createPhoto(input: { title: $title, description: $description }) {
    photo {
      id
      title
      description
    }
  }
}

mutation createPhoto($title: String!, $description: String!, $id: ID!) {
  createPhoto(input: { title: $title, description: $description, id: $id }) {
    photo {
      id
      title
      description
    }
  }
}

